    def minAddToMakeValid(self, s):
        """
        :type s: str
        :rtype: int
        """
        ans = 0
        left_cnt = 0
        for c in s:
            if c == "(":
                left_cnt += 1
            else:
                if left_cnt == 0:
                    ans += 1
                else:
                    left_cnt -= 1
        ans += left_cnt
